func EnSeal(m *enctx.Arenas, chk *port.Cells, out *port.Cells, level int32) int32 {
	// `model-check`, and `model-check-assets` when `level` (the asset level) is on. Answers 0, 1 (`model-check` failed) or 2 (`model-check-assets` did); the code and the node go to `out`.
	var code int32 = model.ModelCheck(m.Nodes, m.Attrs, m.Regions, m.Text, m.Pages, m.Ledger, m.Layout, chk)
	if code != 0 {
		port.CellsPush(out, code)
		port.CellsPush(out, port.CellsAt(chk, 0))
		return 1
	}
	if level != 0 {
		code = model.ModelCheckAssets(m.Nodes, m.Attrs, m.Assets, m.Uses, m.Abytes, chk)
		if code != 0 {
			port.CellsPush(out, code)
			port.CellsPush(out, port.CellsAt(chk, 0))
			return 2
		}
	}
	return 0
}

func enFigures(m *enctx.Arenas, s *enctx.Scratch, d *enctx.Doc, level int32) int32 {
	// P8.1 (SPEC 10.6): the figures, before `rs-run` (a caption next to one finds it as its object): every output has them, at every level of
	// `assets` (which only decides whether they get pixels, and tells the asset stage's candidate rows `cand` what P8.1 found).
	figclass.FcStage(m.Nodes, m.Attrs, m.Regions, m.Text, m.Pages, s.Fnodes, s.Fattrs, s.Fregions, s.Fnm, d.Pa, d.Im, d.Fi, s.Grg, d.Grl, d.Fw, d.Fl, d.Et, d.Pg, s.Sm, d.Cand, level, s.Fcand, s.Fcl, s.Fg, s.Ffd, s.Fab, s.Fws)
	port.CellsSwap(m.Nodes, s.Fnodes)
	port.CellsSwap(m.Attrs, s.Fattrs)
	port.CellsSwap(m.Regions, s.Fregions)
	return 0
}

func enFields(m *enctx.Arenas, s *enctx.Scratch, d *enctx.Doc) int32 {
	// P11.x3 (SPEC 3.2, D1510): the AcroForm fields the annotation reader made rows of (`an-field`) put into the blocks that hold their labels, by geometry (`emon.fields`).
	// A copy of the finished body (the arenas the figures stage left in `fnodes`, `fattrs`, `fregions` are its scratch) swapped in; a document with no field row is not touched.
	var r int32 = fields.FlRun(m.Nodes, m.Attrs, m.Regions, m.Text, s.Fnodes, s.Fattrs, s.Fregions, s.Fnm, d.An, d.Txt, s.Flc, s.Flh, s.Flb, s.Fls)
	if r > 0 {
		port.CellsSwap(m.Nodes, s.Fnodes)
		port.CellsSwap(m.Attrs, s.Fattrs)
		port.CellsSwap(m.Regions, s.Fregions)
	}
	return 0
}

func enAssetStage(c *enctx.Cfg, m *enctx.Arenas, s *enctx.Scratch, cand *port.Cells, cbytes *port.Buf) int32 {
	// P3.13: the settings on the root, then each figure's and seal's pixels or reason, in node-id order. `cand` and `cbytes` were made by the document pass.
	asset.AsSettings(m.Nodes, m.Attrs, m.Text, c.Level, c.Dpi, c.Pixels, c.Abyte, c.Tbyte, c.Sigs)
	port.CellsPush(s.Bx, 0)
	port.CellsPush(s.Bx, 0)
	port.CellsPush(s.Bx, 0)
	port.CellsPush(s.Bx, 0)
	port.CellsPush(s.Bx, 0)
	asset.AsRun(m.Nodes, m.Attrs, m.Regions, cand, cbytes, m.Assets, m.Uses, m.Abytes, c.Abyte, c.Tbyte, c.Sigs, s.Bx)
	return 0
}

